begin;
select set_config('cpr.a',gen_random_uuid()::text,true),set_config('cpr.b',gen_random_uuid()::text,true),set_config('cpr.s',gen_random_uuid()::text,true),set_config('cpr.pa',gen_random_uuid()::text,true),set_config('cpr.pb',gen_random_uuid()::text,true),set_config('cpr.pc',gen_random_uuid()::text,true),set_config('cpr.pd',gen_random_uuid()::text,true),set_config('cpr.ba',gen_random_uuid()::text,true),set_config('cpr.bb',gen_random_uuid()::text,true),set_config('cpr.bc',gen_random_uuid()::text,true),set_config('cpr.bd',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('cpr.a')::uuid,'cpr-a@example.invalid'),(current_setting('cpr.b')::uuid,'cpr-b@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('cpr.a'),'role','authenticated')::text,true);set local role authenticated;
insert into public.products(id,name,sale_price) values(current_setting('cpr.pa')::uuid,'Credit Return A',8000),(current_setting('cpr.pb')::uuid,'Credit Return B',8000),(current_setting('cpr.pc')::uuid,'Credit Return C',8000),(current_setting('cpr.pd')::uuid,'Stock Return D',8000);
insert into public.suppliers(id,name,phone) values(current_setting('cpr.s')::uuid,'Credit Return Supplier','000');
do $$
declare
 s uuid:=current_setting('cpr.s')::uuid;pa uuid:=current_setting('cpr.pa')::uuid;pb uuid:=current_setting('cpr.pb')::uuid;pc uuid:=current_setting('cpr.pc')::uuid;pd uuid:=current_setting('cpr.pd')::uuid;
 ba uuid:=current_setting('cpr.ba')::uuid;bb uuid:=current_setting('cpr.bb')::uuid;bc uuid:=current_setting('cpr.bc')::uuid;bd uuid:=current_setting('cpr.bd')::uuid;
 ra1 uuid:=gen_random_uuid();ra2 uuid:=gen_random_uuid();rb uuid:=gen_random_uuid();rc uuid:=gen_random_uuid();rd uuid:=gen_random_uuid();paya uuid:=gen_random_uuid();payb uuid:=gen_random_uuid();payc uuid:=gen_random_uuid();
 r jsonb;bal bigint;cash bigint;stock bigint;daily jsonb;stmt jsonb;activity jsonb;today date:=(now() at time zone 'Asia/Baghdad')::date;
begin
 perform public.post_cash_entry(gen_random_uuid(),'deposit',100000,'credit-return cash');
 perform public.post_supplier_purchase(ba,jsonb_build_array(jsonb_build_object('product_id',pa,'quantity_units',2000,'unit_cost',5000)),s,2000,'CPR-A','credit A');
 r:=public.post_purchase_return(ra1,ba,'A first debt return',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',600)));
 if (r->>'total')::bigint<>3000 or (r->>'debt_reversed')::bigint<>3000 or (r->>'cash_refund')::bigint<>0 then raise exception 'A first split wrong';end if;
 r:=public.get_supplier_purchase_finance(ba);if (r->>'outstanding')::bigint<>5000 then raise exception 'A outstanding wrong';end if;
 perform public.post_supplier_purchase_payment(paya,ba,3000,'A later payment');
 r:=public.post_purchase_return(ra2,ba,'A mixed return',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',600)));
 if (r->>'total')::bigint<>3000 or (r->>'debt_reversed')::bigint<>2000 or (r->>'cash_refund')::bigint<>1000 then raise exception 'A mixed split wrong';end if;
 r:=public.get_supplier_purchase_finance(ba);if (r->>'outstanding')::bigint<>0 or (r->>'debt_reversed')::bigint<>5000 then raise exception 'A finance not cleared';end if;
 select quantity_units into stock from public.product_stock where product_id=pa;if stock<>800 then raise exception 'A stock wrong';end if;
 perform public.post_supplier_purchase(bb,jsonb_build_array(jsonb_build_object('product_id',pb,'quantity_units',3000,'unit_cost',2000)),s,3000,'CPR-B','credit B');
 perform public.post_supplier_purchase_payment(payb,bb,3000,'B full later payment');
 r:=public.post_purchase_return(rb,bb,'B paid return',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',1000)));
 if (r->>'total')::bigint<>2000 or (r->>'debt_reversed')::bigint<>0 or (r->>'cash_refund')::bigint<>2000 then raise exception 'B cash split wrong';end if;
 perform public.post_supplier_purchase(bc,jsonb_build_array(jsonb_build_object('product_id',pc,'quantity_units',3000,'unit_cost',3000)),s,1000,'CPR-C','credit C');
 perform public.post_supplier_purchase_payment(payc,bc,3000,'C partial payment');
 r:=public.post_purchase_reversal(rc,bc,'C full credit reversal');
 if (r->>'total')::bigint<>9000 or (r->>'debt_reversed')::bigint<>5000 or (r->>'cash_refund')::bigint<>4000 then raise exception 'C full split wrong';end if;
 r:=public.get_supplier_purchase_finance(bc);if (r->>'outstanding')::bigint<>0 then raise exception 'C finance not cleared';end if;
 select quantity_units into stock from public.product_stock where product_id=pc;if stock<>0 then raise exception 'C stock not reversed';end if;
 perform public.post_purchase(bd,jsonb_build_array(jsonb_build_object('product_id',pd,'quantity_units',1000,'unit_cost',4000)),'Legacy Stock','CPR-D','untracked D');
 r:=public.post_purchase_return(rd,bd,'D stock only return',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',500)));
 if (r->>'total')::bigint<>2000 or (r->>'debt_reversed')::bigint<>0 or (r->>'cash_refund')::bigint<>0 then raise exception 'D split wrong';end if;
 select balance into bal from public.supplier_balances where supplier_id=s;if bal<>0 then raise exception 'supplier balance not cleared';end if;
 select balance into cash from public.cash_accounts where owner_id=auth.uid();if cash<>92000 then raise exception 'cash balance wrong';end if;
 if (select coalesce(sum(amount),0) from public.supplier_entries where supplier_id=s and kind='reversal')<>10000 then raise exception 'supplier reversals wrong';end if;
 daily:=public.get_daily_report(today);if (daily->'purchase_returns'->>'count')::bigint<>5 or (daily->'purchase_returns'->>'total')::bigint<>19000 or (daily->'purchase_returns'->>'cash_refund')::bigint<>7000 or (daily->'purchase_returns'->>'debt_reversed')::bigint<>10000 or (daily->'purchase_returns'->>'untracked_count')::bigint<>1 then raise exception 'daily return split wrong';end if;
 stmt:=public.get_supplier_statement(s,null,null);if (stmt->>'charges')::bigint<>19000 or (stmt->>'payments')::bigint<>9000 or (stmt->>'returns_total')::bigint<>17000 or (stmt->>'reversals')::bigint<>10000 or (stmt->>'closing')::bigint<>0 then raise exception 'supplier statement wrong';end if;
 if exists(select 1 from jsonb_array_elements(stmt->'rows') x where x->>'kind'='return' and (x->>'delta')::bigint<>-(x->>'debt_reversed')::bigint) then raise exception 'statement return delta mismatch';end if;
 activity:=public.get_supplier_activity(s,0,50);if (activity->>'total')::int<>10 then raise exception 'supplier activity count wrong';end if;
 if not exists(select 1 from jsonb_array_elements(activity->'rows') x where x->>'reference_no' like 'PRV-%' and (x->>'cash_refund')::bigint=4000 and (x->>'debt_reversed')::bigint=5000) then raise exception 'full credit return missing';end if;
 r:=public.get_purchase_returns_report('all',null,null,null,'CPR-C',null,null,0,50);if (r->>'count')::int<>1 or (r->'rows'->0->>'cash_refund')::bigint<>4000 or (r->'rows'->0->>'debt_reversed')::bigint<>5000 then raise exception 'returns center split missing';end if;
end $$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('cpr.b'),'role','authenticated')::text,true);set local role authenticated;
do $$ declare r jsonb; begin r:=public.get_purchase_returns_report('all',null,null,null,null,null,null,0,50);if (r->>'count')::int<>0 then raise exception 'cross-owner return leak';end if;end $$;
reset role;set local role anon;
do $$ begin begin perform public.post_purchase_return(gen_random_uuid(),current_setting('cpr.ba')::uuid,'anon',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',1)));raise exception 'anon return allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
select 'PASS: credit purchase partial/full returns split debt and cash, reconcile stock/supplier/cash, update finance/reports/activity, preserve untracked behavior and RLS' verification;
rollback;
